require "rails_helper"

RSpec.describe Timekeeping::ReservationRules do
  # "Keep the rows in the same order: not in company → not_found; provisional → provisional_elsewhere; committed by the same invoice → keep; committed active elsewhere → on_another_invoice; otherwise add_provisional."
  it "gives the same prepare outcome as before for each set of entry facts" do
    active_elsewhere = { invoice_id: 20, disposition: "active" }
    retained_elsewhere = { invoice_id: 20, disposition: "retained" }
    same_invoice = { invoice_id: 10, disposition: "active" }
    provisional = { invoice_id: 30 }
    cases = {
      { in_company: false, committed: nil, provisional:, invoice_id: 10 } => :not_found,
      { in_company: false, committed: active_elsewhere, provisional: nil, invoice_id: 10 } => :not_found,
      { in_company: true, committed: nil, provisional:, invoice_id: 10 } => :provisional_elsewhere,
      { in_company: true, committed: same_invoice, provisional: nil, invoice_id: 10 } => :keep,
      { in_company: true, committed: active_elsewhere, provisional: nil, invoice_id: 10 } => :on_another_invoice,
      { in_company: true, committed: retained_elsewhere, provisional: nil, invoice_id: 10 } => :add_provisional,
      { in_company: true, committed: nil, provisional: nil, invoice_id: 10 } => :add_provisional
    }

    expect(cases.keys.map { |entry| described_class.prepare_outcome(entry) }).to eq(cases.values)
    expect(described_class::PREPARE_TABLE).to be_frozen
    expect(described_class::PREPARE_TABLE).to all(be_frozen)
  end
end

require "rails_helper"

RSpec.describe Timekeeping::ReservationRules do
  it "refuses exactly the conflict reasons the reservations contract lists" do
    contract = YAML.safe_load_file(Rails.root.join("contracts/timekeeping/reservations.yml"))
    outcomes = %i[not_found provisional_elsewhere keep on_another_invoice add_provisional]

    refused = outcomes.select { |outcome| described_class.refusal?(outcome) }

    expect(refused).to match_array(%i[not_found provisional_elsewhere on_another_invoice])
    expect(refused.map(&:to_s)).to match_array(contract.fetch("conflict_reasons"))
    expect(TimekeepingContract::ReservationRules).to equal(described_class)
  end
end
